<form class="row g-2 mb-3" method="get">
 <div class="col-md-3"><select name="partner_id" class="form-select"><option value="">Semua travel</option><?php foreach ($partners as $p): ?><option value="<?= $p->id ?>"<?= sel($f['partner_id'] ?? '', $p->id) ?>><?= e($p->name) ?></option><?php endforeach; ?></select></div>
 <div class="col-md-2"><select name="category" class="form-select"><option value="">Semua kategori</option><?php foreach (['local' => 'Lokal', 'international' => 'Luar Negeri', 'hajj' => 'Haji', 'umrah' => 'Umroh'] as $k => $v): ?><option value="<?= $k ?>"<?= sel($f['category'] ?? '', $k) ?>><?= $v ?></option><?php endforeach; ?></select></div>
 <div class="col-md-2"><select name="status" class="form-select"><option value="">Semua status</option><?php foreach (['pending', 'partially_paid', 'paid', 'completed', 'cancelled', 'expired', 'refunded'] as $s): ?><option<?= sel($f['status'] ?? '', $s) ?>><?= $s ?></option><?php endforeach; ?></select></div>
 <div class="col-md-2"><input type="date" name="from" value="<?= e($f['from'] ?? '') ?>" class="form-control"></div><div class="col-md-2"><input type="date" name="to" value="<?= e($f['to'] ?? '') ?>" class="form-control"></div>
 <div class="col-md-1"><button class="btn btn-primary w-100">Filter</button></div></form>
<div class="card p-3"><table class="table table-hover dt"><thead><tr><th>Kode</th><th>Customer</th><th>Paket</th><th>Travel</th><th>Berangkat</th><th>Total</th><th>Dibayar</th><th>Status</th><th></th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr><td><?= e($r->booking_code) ?></td><td><?= e($r->customer) ?></td><td><?= e($r->package_name_snapshot) ?></td><td><?= e($r->partner_name_snapshot) ?></td><td><?= fdate($r->departure_date) ?></td><td><?= rupiah($r->total_amount) ?></td><td><?= rupiah($r->paid_amount) ?></td><td><?= badge($r->status) ?></td>
<td><a class="btn btn-sm btn-outline-primary" href="<?= site_url('admin/bookings/show/' . $r->id) ?>">Detail</a></td></tr><?php endforeach; ?></tbody></table></div>
